package com.primehr.evidence.domain;

import com.primehr.rsp.domain.RspAuditedEntity;
import jakarta.persistence.*;
import java.time.*;

@Entity @Table(name="evidence_assessment_cycle",uniqueConstraints=@UniqueConstraint(name="uk_evidence_cycle_code",columnNames={"agency_id","normalized_code"}))
public class EvidenceAssessmentCycle extends RspAuditedEntity{
 public enum Status{DRAFT,OPEN,CLOSED,CANCELLED}
 @Column(nullable=false,length=80)private String code;@Column(name="normalized_code",nullable=false,length=80)private String normalizedCode;@Column(nullable=false,length=200)private String title;@Column(length=2000)private String description;
 @Column(name="framework_version_id",nullable=false,length=36)private String frameworkVersionId;@Column(name="framework_definition_version",nullable=false)private int frameworkDefinitionVersion;@Column(name="framework_content_revision",nullable=false)private int frameworkContentRevision;@Column(name="framework_fingerprint",nullable=false,length=64)private String frameworkFingerprint;
 @Column(name="period_start",nullable=false)private LocalDate periodStart;@Column(name="period_end",nullable=false)private LocalDate periodEnd;@Column(name="due_date",nullable=false)private LocalDate dueDate;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Status status;@Column(name="opened_by",length=100)private String openedBy;@Column(name="opened_at")private Instant openedAt;@Column(name="closed_by",length=100)private String closedBy;@Column(name="closed_at")private Instant closedAt;@Column(name="transition_reason",length=2000)private String transitionReason;
 protected EvidenceAssessmentCycle(){}public EvidenceAssessmentCycle(String a,String code,String title,String description,String framework,int definition,int revision,String fingerprint,LocalDate start,LocalDate end,LocalDate due){super(a);this.code=requiredText(code,"code");normalizedCode=this.code.toUpperCase(java.util.Locale.ROOT);apply(title,description,start,end,due);frameworkVersionId=requiredText(framework,"frameworkVersionId");if(definition<1||revision<1)throw new IllegalArgumentException("Published framework version and content revision are required");frameworkDefinitionVersion=definition;frameworkContentRevision=revision;frameworkFingerprint=requiredText(fingerprint,"frameworkFingerprint");status=Status.DRAFT;}
 public void update(String title,String description,LocalDate start,LocalDate end,LocalDate due){draft();apply(title,description,start,end,due);}private void apply(String title,String description,LocalDate start,LocalDate end,LocalDate due){this.title=requiredText(title,"title");this.description=optionalText(description);if(start==null||end==null||end.isBefore(start))throw new IllegalArgumentException("A valid assessment period is required");if(due==null||due.isBefore(end))throw new IllegalArgumentException("dueDate cannot precede periodEnd");periodStart=start;periodEnd=end;dueDate=due;}
 public void open(String actor,String reason,Instant at){draft();openedBy=requiredText(actor,"actor");openedAt=at;transitionReason=requiredText(reason,"reason");status=Status.OPEN;}public void close(String actor,String reason,Instant at){if(status!=Status.OPEN)throw new IllegalStateException("Only an open cycle may be closed");closedBy=requiredText(actor,"actor");closedAt=at;transitionReason=requiredText(reason,"reason");status=Status.CLOSED;}public void cancel(String actor,String reason,Instant at){if(status!=Status.DRAFT&&status!=Status.OPEN)throw new IllegalStateException("Only a draft or open cycle may be cancelled");closedBy=requiredText(actor,"actor");closedAt=at;transitionReason=requiredText(reason,"reason");status=Status.CANCELLED;}private void draft(){if(status!=Status.DRAFT)throw new IllegalStateException("Only a draft cycle may be changed");}
 public String getCode(){return code;}public String getTitle(){return title;}public String getDescription(){return description;}public String getFrameworkVersionId(){return frameworkVersionId;}public int getFrameworkDefinitionVersion(){return frameworkDefinitionVersion;}public int getFrameworkContentRevision(){return frameworkContentRevision;}public String getFrameworkFingerprint(){return frameworkFingerprint;}public LocalDate getPeriodStart(){return periodStart;}public LocalDate getPeriodEnd(){return periodEnd;}public LocalDate getDueDate(){return dueDate;}public Status getStatus(){return status;}public String getOpenedBy(){return openedBy;}public Instant getOpenedAt(){return openedAt;}public String getClosedBy(){return closedBy;}public Instant getClosedAt(){return closedAt;}public String getTransitionReason(){return transitionReason;}
}
